function animate(timestamp) {
  if (!isPaused) {
    const elapsed = timestamp - lastTime;
    window.demo.setTime((elapsed / 1000) % 1); // t in [0,1] loop
    lastTime = timestamp;

    animFrameId = requestAnimationFrame(animate);
  }
}

