function drawEditionCoin(canvas, edition) {
  const ctx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;
  const cx = w / 2;
  const cy = h / 2;

  // Draw coin with metallic effect
  drawMetallicCoin(ctx, edition);
}

function drawMetallicCoin(ctx, edition) {
  const cx = ctx.canvas.width / 2;
  const cy = ctx.canvas.height / 2;
  const radius = Math.min(cx, cy) - 40; // keep within bounds

  // Create radial gradient for metallic effect
  const grad = ctx.createRadialGradient(
    cx - 30, cy - 30, 5,
    cx, cy, radius + 10
  );

  grad.addColorStop(0, edition.gradientStart);
  grad.addColorStop(0.4, edition.color);
  grad.addColorStop(0.7, edition.shadowColor);
  grad.addColorStop(1, '#0a0a0f');

  // Draw coin body with rounded corners (ellipse)
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx, cy, radius + 20, radius + 20, 0, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();

  // Add metallic highlight that moves with rotation effect
  const highlightX = cx - 50 + Math.sin(Date.now() / 1000) * 40;
  const highlightY = cy - 50 + Math.cos(Date.now() / 1000) * 30;

  ctx.save();
  ctx.beginPath();
  ctx.ellipse(highlightX, highlightY, radius * 0.25, radius * 0.15, 
              Math.sin(Date.now() / 800), 0, Math.PI * 2);
  ctx.fillStyle = edition.highlight;
  ctx.fill();
  ctx.restore();

  // Front face emblem area (slightly different shade)
  ctx.save();
  const frontGrad = ctx.createRadialGradient(cx - 40, cy - 50, 10, cx, cy, radius * 0.8);
  frontGrad.addColorStop(0, edition.highlight + '66');
  frontGrad.addColorStop(1, 'transparent');

  ctx.beginPath();
  ctx.arc(cx, cy, radius * 0.95, 0, Math.PI * 2);
  ctx.fillStyle = frontGrad;
  ctx.fill();

  // Draw emblem pattern (procedural)
  ctx.save();
  ctx.translate(cx, cy - 10);

  // Outer ring of emblem
  ctx.beginPath();
  ctx.arc(0, 0, radius * 0.35, 0, Math.PI * 2);
  ctx.strokeStyle = edition.color;
  ctx.lineWidth = 2;
  ctx.stroke();

  // Inner details
  ctx.font = `${radius * 0.15}px serif`;
  ctx.textAlign = 'center';
  ctx.fillStyle = edition.gradientStart;
  ctx.fillText('WM', -3, radius * 0.2);

  // Decorative lines
  for (let i = -60; i <= 60; i += 15) {
    ctx.beginPath();
    ctx.moveTo(i, -radius * 0.45);
    ctx.lineTo(i, radius * 0.35);
    ctx.strokeStyle = edition.shadowColor + '44';
    ctx.lineWidth = 1;
    ctx.stroke();
  }

  ctx.restore();
  ctx.restore();

  // Back face denomination area (different shading)
  ctx.save();
  const backGrad = ctx.createRadialGradient(cx + 30, cy + 40, 10, cx, cy, radius * 0.85);
  backGrad.addColorStop(0, edition.highlight + '22');
  backGrad.addColorStop(1, 'transparent');

  ctx.beginPath();
  ctx.arc(cx, cy, radius * 0.9, 0, Math.PI * 2);
  ctx.fillStyle = backGrad;
  ctx.fill();

  // Draw denomination text area pattern
  ctx.save();
  ctx.translate(cx + 15, cy + 30);

  ctx.font = `${radius * 0.18}px serif`;
  ctx.textAlign = 'center';
  ctx.fillStyle = edition.color;
  ctx.fillText('TOKENS', -40, radius * 0.2);

  // Number display area
  ctx.font = `${radius * 0.35}px sans-serif`;
  ctx.fillStyle = edition.gradientStart;
  ctx.fillText('10,000', -40, radius * 0.6);

  // Small text below
  ctx.font = `${radius * 0.12}px serif`;
  ctx.fillStyle = edition.shadowColor + '88';
  ctx.fillText('DENOMINATION', -35, radius * 0.75);

  ctx.restore();
  ctx.restore();

  // Reeded edge effect (concentric circles)
  ctx.save();
  for (let i = 0; i < 12; i++) {
    const r = radius + 10 - i * 3;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.strokeStyle = edition.shadowColor + (i % 3 === 0 ? '66' : '33');
    ctx.lineWidth = 1.5;
    ctx.stroke();
  }

  // Outer rim highlight
  ctx.save();
  const rimGrad = ctx.createLinearGradient(cx - radius, cy - radius, cx + radius, cy + radius);
  rimGrad.addColorStop(0, edition.highlight + '44');
  rimGrad.addColorStop(1, 'transparent');

  ctx.beginPath();
  ctx.arc(cx, cy, radius + 5, 0, Math.PI * 2);
  ctx.strokeStyle = rimGrad;
  ctx.lineWidth = 3;
  ctx.stroke();

  ctx.restore();

  // Shadow under coin
  ctx.save();
  const shadowGrad = ctx.createRadialGradient(cx - 15, cy + radius + 10, 5, cx, cy + radius + 20, 60);
  shadowGrad.addColorStop(0, 'rgba(0,0,0,0.3)');
  shadowGrad.addColorStop(1, 'transparent');

  ctx.beginPath();
  ctx.arc(cx, cy + radius + 15, radius + 25, 0, Math.PI * 2);
  ctx.fillStyle = shadowGrad;
  ctx.fill();

  ctx.restore();

  ctx.restore();
}

